/* Generated by port_site.py from the approved mockup. Behaviour for the hero section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce,
    root = document.documentElement;

  /* rotating last line (Wati) */
  var ROT = [
      "WhatsApp at 2 AM",
      "Instagram DM",
      "missed call",
      "booking enquiry",
      "story reply",
      "voice note",
    ],
    ri = 0,
    rt = null;
  var hw = document.getElementById("hlword"),
    ht = document.getElementById("hltext");
  function rotate() {
    if (reduce || document.hidden) {
      rt = null;
      return;
    }
    rt = ctx.setTimeout(function () {
      hw.classList.add("out");
      ctx.setTimeout(function () {
        ri = (ri + 1) % ROT.length;
        ht.textContent = ROT[ri];
        hw.classList.remove("out");
        rotate();
      }, 380);
    }, 2600);
  }

  /* conversation stream: starts filled, then keeps adding items at the bottom and scrolls up */
  var feed = document.getElementById("feed"),
    items = [].slice.call(document.getElementById("tpl").children),
    fi = 0,
    ft = null;
  function add(animate) {
    var n = items[fi % items.length].cloneNode(true);
    fi++;
    if (animate) n.classList.add("new");
    feed.appendChild(n);
    if (animate)
      ctx.raf(function () {
        ctx.raf(function () {
          n.classList.remove("new");
        });
      });
  }
  function trim() {
    var box = feed.parentElement.getBoundingClientRect().height;
    while (feed.scrollHeight > box + 260 && feed.children.length > 4) {
      feed.removeChild(feed.firstElementChild);
    }
    var over = feed.scrollHeight - box;
    feed.style.transform = "translateY(" + -Math.max(0, over) + "px)";
  }
  function tick() {
    if (reduce || document.hidden) {
      ft = null;
      return;
    }
    ft = ctx.setTimeout(function () {
      add(true);
      trim();
      tick();
    }, 1700);
  }
  for (var k = 0; k < 7; k++) add(false);
  trim();

  ctx.on(document, "visibilitychange", function () {
    if (document.hidden) return;
    if (!rt) rotate();
    if (!ft) tick();
  });
  ctx.on(window, "resize", trim);
  rotate();
  tick();

  ctx.cleanup(function () {
    var f = document.getElementById("feed");
    if (f) f.innerHTML = "";
  });
}
